programa
{
    inclua biblioteca Matematica

    funcao real area_circulo(real raio)
    {
        se (raio < 0)
        {
            retorne 0
        }
        retorne Matematica.PI * Matematica.potencia(raio, raio)
    }

    funcao inicio()
    {
        real raio
        escreva("Digite o raio: ")
        leia(raio)
        escreva("Area: ", area_circulo(raio), "\n")
    }
}

